import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { ABOUT_LINKS } from './about.js';
import { SubPage } from './SettingsKit.js';
import styles from './Settings.module.css';

const LINKS = [
  { href: ABOUT_LINKS.features, labelKey: 'settings.aboutFeatures' },
  { href: ABOUT_LINKS.changelog, labelKey: 'settings.aboutChangelog' },
  { href: ABOUT_LINKS.privacy, labelKey: 'settings.aboutPrivacy' },
  { href: ABOUT_LINKS.terms, labelKey: 'settings.aboutTerms' },
] as const;

/**
 * Help & about: the public pages that explain what Lexpad does, what has
 * changed and the terms it is offered on, and which version this is. The
 * links are plain new-tab links, which the shells hand to the system browser.
 */
export function AboutSettings(): React.JSX.Element {
  return (
    <SubPage title={t('settings.page.about')}>
      <div className={styles.group}>
        {LINKS.map((link) => (
          <a
            key={link.href}
            href={link.href}
            target="_blank"
            rel="noopener noreferrer"
            className={cx(styles.row, styles.button, styles.navRow)}
          >
            <span className={cx(styles.label, styles.navLabel)}>{t(link.labelKey)}</span>
            <Icon name="chevronRight" size={18} weight={2} className={styles.chevron} />
          </a>
        ))}
      </div>
      <div className={styles.group}>
        <div className={cx(styles.row, styles.rowStatic)}>
          <span className={styles.label}>{t('settings.version')}</span>
          <span className={styles.value}>{platform.env.appVersion}</span>
        </div>
      </div>
    </SubPage>
  );
}
