import { t } from '@/i18n/index.js';
import { StatusLine, SubPage } from '@/features/settings/SettingsKit.js';
import { useSay } from '@/features/settings/useSay.js';
import { Everywhere } from './Everywhere.js';
import styles from './Everywhere.module.css';

/** Settings → Lexpad everywhere, also at /settings/everywhere for the cards and links that name it. */
export function EverywhereSettings(): React.JSX.Element {
  const { status, failed, say } = useSay();
  return (
    <SubPage title={t('everywhere.title')}>
      <p className={styles.lead}>{t('everywhere.lead')}</p>
      <Everywhere say={say} />
      <StatusLine status={status} failed={failed} />
    </SubPage>
  );
}
