import { t } from '@/i18n/index.js';
import { ConnectedApps } from './ConnectedApps.js';
import { StatusLine, SubPage } from './SettingsKit.js';
import { useSay } from './useSay.js';

/** Connected apps: the assistants that can reach the notebook, and the way to connect one. */
export function ConnectedAppsSettings(): React.JSX.Element {
  const { status, failed, say } = useSay();
  return (
    <SubPage title={t('settings.page.connectedApps')}>
      <ConnectedApps say={say} />
      <StatusLine status={status} failed={failed} />
    </SubPage>
  );
}
