import type { GradingMode, NewWordOrder } from '@lexpad/core';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { toggleCardType } from '@/db/mutations.js';
import { syncSoon } from '@/sync/store.js';
import { LANGUAGE_NAMES, LOADING, loadSettingsScreen } from './data.js';
import { CARD_TYPES, GRADING } from './options.js';
import { saveSettings } from './save.js';
import { Section, Slider, SubPage, SwitchRow } from './SettingsKit.js';
import { PRACTICE_STYLES, STYLE_LABELS, stylesOf, withStyle } from './style.js';
import styles from './Settings.module.css';

/**
 * Practice: how much a day brings, which kinds of card it is made of, how
 * strictly typing is marked and which new words come first; then sound,
 * which is part of how a session feels. Which notebooks a session draws
 * from is chosen in the notebook sheet, beside the notebooks themselves.
 */
export function PracticeSettings(): React.JSX.Element {
  const { settings, notebook } = useLiveQuery(loadSettingsScreen, LOADING, []);
  const targetName = LANGUAGE_NAMES[notebook?.targetLang ?? 'en'];
  const chosenStyles = stylesOf(settings.cardTypes);

  return (
    <SubPage title={t('settings.page.practice')}>
      <Section title={t('settings.practice')}>
        <div className={styles.group}>
          <Slider
            label={t('settings.newPerDay')}
            value={settings.newPerDay}
            min={5}
            max={40}
            step={5}
            onChange={(newPerDay) => {
              saveSettings({ newPerDay });
            }}
          />
          <Slider
            label={t('settings.sessionCap')}
            value={settings.sessionCap}
            min={10}
            max={60}
            step={5}
            onChange={(sessionCap) => {
              saveSettings({ sessionCap });
            }}
          />
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={styles.label}>{t('settings.practiceStyle')}</span>
            {/* Several at once, because the three divide the card types
                between them and practising two of them is an ordinary thing
                to want. There is no "mixed": that was all three, which is
                now just all three chosen. */}
            <div className={styles.tray} role="group" aria-label={t('settings.practiceStyle')}>
              {PRACTICE_STYLES.map((style) => {
                const on = chosenStyles.includes(style);
                return (
                  <button
                    key={style}
                    type="button"
                    className={cx(styles.trayButton, on && styles.trayOn)}
                    aria-pressed={on}
                    onClick={() => {
                      saveSettings({ cardTypes: withStyle(style, !on, settings.cardTypes) });
                    }}
                  >
                    {t(STYLE_LABELS[style])}
                  </button>
                );
              })}
            </div>
          </div>
          <p className={styles.groupNote}>{t('settings.practiceStyleNote')}</p>
          {CARD_TYPES.map((type) => {
            const on = settings.cardTypes.includes(type.value);
            return (
              <SwitchRow
                key={type.value}
                label={t(type.labelKey)}
                checked={on}
                dim={!on}
                onChange={() => {
                  void toggleCardType(type.value).then(() => syncSoon());
                }}
              />
            );
          })}
          <div className={cx(styles.row, styles.rowStatic)}>
            <span className={styles.label}>{t('settings.typedGrading')}</span>
            <select
              className={styles.select}
              aria-label={t('settings.typedGrading')}
              value={settings.typedGrading}
              onChange={(event) => {
                saveSettings({ typedGrading: event.target.value as GradingMode });
              }}
            >
              {GRADING.map((entry) => (
                <option key={entry.value} value={entry.value}>
                  {t(entry.labelKey)}
                </option>
              ))}
            </select>
          </div>
          {/* Stacked, not side by side: "From the start of the notebook" makes
              the closed select wide enough to squeeze the label into four
              lines of one word each. */}
          <div className={cx(styles.row, styles.rowStatic, styles.rowStacked)}>
            <span className={styles.label}>{t('settings.newWordOrder')}</span>
            <select
              className={styles.select}
              aria-label={t('settings.newWordOrder')}
              value={settings.newWordOrder}
              onChange={(event) => {
                saveSettings({ newWordOrder: event.target.value as NewWordOrder });
              }}
            >
              <option value="newest">{t('settings.newNewest')}</option>
              <option value="start">{t('settings.newStart')}</option>
              <option value="shuffle">{t('settings.newShuffle')}</option>
            </select>
          </div>
        </div>
      </Section>

      <Section title={t('settings.sound')}>
        <div className={styles.group}>
          <SwitchRow
            label={t('settings.autoSpeak', { language: targetName })}
            checked={settings.autoSpeak}
            onChange={(autoSpeak) => {
              saveSettings({ autoSpeak });
            }}
          />
          <SwitchRow
            label={t('settings.speakExamples')}
            checked={settings.speakExamples}
            onChange={(speakExamples) => {
              saveSettings({ speakExamples });
            }}
          />
        </div>
      </Section>
    </SubPage>
  );
}
