import { useCallback, useState } from 'react';

/** A one-line message under a Settings page: what just happened, or what went wrong. */
export interface Say {
  status: string | undefined;
  failed: boolean;
  say: (message: string, isError?: boolean) => void;
}

/** The status line each Settings page keeps for the outcome of its own actions. */
export function useSay(): Say {
  const [status, setStatus] = useState<string | undefined>(undefined);
  const [failed, setFailed] = useState(false);
  const say = useCallback((message: string, isError = false): void => {
    setStatus(message);
    setFailed(isError);
  }, []);
  return { status, failed, say };
}
