import { notebooks as notebooksApi } from '@/api/endpoints.js';
import type { ApiImportJob } from '@/api/types.js';

/**
 * Whether a file is SQLite, from its own first bytes rather than its name:
 * a Kindle's vocab.db is often copied off the device under another name.
 */
export async function isSqlite(file: File): Promise<boolean> {
  const magic = 'SQLite format 3';
  const head = await file.slice(0, magic.length).text();
  return head === magic;
}

/** How long to wait for a server-side import before giving up on watching. */
const IMPORT_POLL_MS = 600;
const IMPORT_POLL_TRIES = 100;

/** Watches a server import to the end, or until it is clearly stuck. */
export async function waitForImport(jobId: string): Promise<ApiImportJob> {
  let job = await notebooksApi.importStatus(jobId);
  for (let tries = 0; tries < IMPORT_POLL_TRIES; tries += 1) {
    if (job.status === 'done' || job.status === 'failed') return job;
    await new Promise((resolve) => setTimeout(resolve, IMPORT_POLL_MS));
    job = await notebooksApi.importStatus(jobId);
  }
  return job;
}
