/**
 * A practice style is a named set of card types. The setting that syncs is
 * the set itself, so a style is only a convenient way to choose one; a set
 * that matches no style shows as custom.
 */
import type { EnabledCardType } from '@lexpad/core';
import type { t } from '@/i18n/index.js';

export type PracticeStyle = 'cards' | 'quiz' | 'typing';

/**
 * The three styles divide the five card types between them exactly: nothing
 * belongs to two, and nothing belongs to none. That is what lets them be
 * chosen together rather than one at a time — and it is also why there is no
 * "mixed" any more. Mixed was all three at once, which is now something you
 * can simply say.
 */
const PRESETS: Record<PracticeStyle, readonly EnabledCardType[]> = {
  cards: ['classic', 'reverse'],
  quiz: ['mc', 'cloze'],
  typing: ['spell'],
};

export const PRACTICE_STYLES: readonly PracticeStyle[] = ['cards', 'quiz', 'typing'];

/**
 * The styles a set of card types has switched on in full.
 *
 * A style with only some of its types on does not count as chosen: the
 * switches below are finer than the styles, and claiming a style somebody
 * has half of would make the row lie about what a session will ask.
 */
export function stylesOf(types: readonly EnabledCardType[]): PracticeStyle[] {
  const have = new Set(types);
  return PRACTICE_STYLES.filter((style) => PRESETS[style].every((type) => have.has(type)));
}

/**
 * The card types after switching one style on or off, with the others left
 * exactly as they are. Turning the last one off is refused: a session with
 * nothing to ask is not a session.
 */
export function withStyle(
  style: PracticeStyle,
  on: boolean,
  current: readonly EnabledCardType[],
): EnabledCardType[] {
  const preset = PRESETS[style];
  if (on) return [...new Set([...current, ...preset])];
  const rest = current.filter((type) => !preset.includes(type));
  return rest.length === 0 ? [...current] : rest;
}

/** How each style is named in the pickers. */
export const STYLE_LABELS: Record<PracticeStyle, Parameters<typeof t>[0]> = {
  cards: 'settings.styleCards',
  quiz: 'settings.styleQuiz',
  typing: 'settings.styleTyping',
};
