import type { ApiUserSession } from '@/api/types.js';
import { t } from '@/i18n/index.js';

/** A device as the learner would name it: platform, then what the shell reported. */
export function deviceTitle(device: ApiUserSession): string {
  const platform =
    device.platform === 'android'
      ? t('settings.platformAndroid')
      : device.platform === 'ios'
        ? t('settings.platformIos')
        : device.platform === 'extension'
          ? t('settings.platformExtension')
          : device.platform === 'desktop'
            ? t('settings.platformDesktop')
            : t('settings.platformWeb');
  const detail = [device.deviceName, device.appVersion].filter((part) => part !== undefined && part !== '');
  return detail.length === 0 ? platform : `${platform} · ${detail.join(' ')}`;
}

/**
 * How the account signs in, in words: "Google and password". The providers
 * are known once the profile has been read; before that there is nothing to
 * say, and the row is not shown.
 */
export function signInMethods(providers: readonly string[], locale: string): string {
  const names = providers.map((provider) =>
    provider === 'password'
      ? t('settings.methodPassword')
      : provider === 'google'
        ? t('settings.methodGoogle')
        : provider === 'apple'
          ? t('settings.methodApple')
          : provider,
  );
  return new Intl.ListFormat(locale, { style: 'long', type: 'unit' }).format(names);
}
