import { useEffect, useState } from 'react';
import { platform } from '@/lib/platform/index.js';
import type { WebPushSupport } from '@/lib/platform/types.js';
import { useWebPushKey } from '@/lib/useConfig.js';
import { turnOffBrowserPush, turnOnBrowserPush } from '@/features/auth/session.js';

/**
 * What Settings shows for notifications in this browser.
 *
 * - `hidden`: nothing. The server has no VAPID key (so nothing could be
 *   sent), the browser has no Push API or service worker, or this is a
 *   native shell, which has its own push.
 * - `install`: iPhone or iPad Safari in a tab. Apple gives push only to a
 *   site on the Home Screen, so the one useful thing to say is how to get
 *   there; a switch that could never work would be a lie.
 * - `switch`: the switch, on while this browser holds a subscription.
 */
export type BrowserPushView =
  | { kind: 'hidden' }
  | { kind: 'install' }
  | { kind: 'switch'; on: boolean; busy: boolean; problem: 'denied' | 'failed' | undefined };

export function useBrowserPush(): { view: BrowserPushView; toggle: (on: boolean) => void } {
  const key = useWebPushKey();
  const [support, setSupport] = useState<WebPushSupport | undefined>();
  const [on, setOn] = useState(false);
  const [busy, setBusy] = useState(false);
  const [problem, setProblem] = useState<'denied' | 'failed' | undefined>();

  useEffect(() => {
    let live = true;
    void Promise.all([platform.webPush.support(), platform.webPush.subscription()]).then(
      ([answer, subscription]) => {
        if (!live) return;
        setSupport(answer);
        setOn(subscription !== null);
      },
      () => {
        if (live) setSupport('unavailable');
      },
    );
    return () => {
      live = false;
    };
  }, []);

  const toggle = (next: boolean): void => {
    if (busy || key === undefined) return;
    setBusy(true);
    setProblem(undefined);
    const work = next
      ? turnOnBrowserPush(key).then((outcome) => {
          setOn(outcome === 'on');
          if (outcome !== 'on') setProblem(outcome);
        })
      : turnOffBrowserPush().then(() => {
          setOn(false);
        });
    void work
      .catch(() => {
        setProblem('failed');
      })
      .finally(() => {
        setBusy(false);
      });
  };

  let view: BrowserPushView = { kind: 'hidden' };
  if (key !== undefined && support === 'needsInstall') view = { kind: 'install' };
  else if (key !== undefined && support === 'available') view = { kind: 'switch', on, busy, problem };
  return { view, toggle };
}
