/**
 * The rows of "Lexpad everywhere", worked out from the device this is and
 * what the server says the account has used. Pure, so every combination of
 * device and history can be tested without a screen.
 *
 * Every row tells the truth about this device: a store link is offered only
 * where it can be used, a phone is offered "send me the link" for the
 * things that live on a computer, and nothing the server has not released
 * gets a link at all.
 */
import type { ApiSurface, ApiSurfaceStatus } from '@/api/types.js';
import type { MessageKey } from '@/i18n/index.js';
import { extensionStore, type Device } from '@/lib/platform/device.js';
import { DESKTOP_PAGE_URL, EXTENSION_PAGE_URL, EXTENSION_STORES, PLAY_URL, withRef } from './links.js';

/** The ref every link from the hub carries. */
export const HUB_REF = 'hub';

export type HubRowId = 'device' | Exclude<ApiSurface, 'web'>;

/** `unknown` until the server has answered once: no status is claimed and no link offered. */
export type HubStatus = 'here' | 'connected' | 'notYet' | 'notHere' | 'coming' | 'unknown';

export type AssistantTab = 'chatgpt' | 'claude' | 'claudeCode';

export type HubAction =
  /** A link out: a store or the site. */
  | { kind: 'link'; href: string; label: MessageKey }
  /** Pass a link on to another device: the share sheet, or the clipboard. */
  | { kind: 'send'; url: string; label: MessageKey }
  /** The steps for connecting an assistant, on its own tab. */
  | { kind: 'assistant'; tab: AssistantTab; label: MessageKey }
  /** Settings → Data, where a Kindle file is imported. */
  | { kind: 'import'; label: MessageKey }
  /** Nothing to do here, and a short note why. */
  | { kind: 'none'; note?: MessageKey };

export interface HubRow {
  id: HubRowId;
  status: HubStatus;
  /** Marked Beta: listed, linked, never suggested on Today. */
  beta: boolean;
  lastUsedAt?: string | undefined;
  /** Words a Kindle brought in. */
  count?: number | undefined;
  action: HubAction;
}

/** The surfaces, in the order the hub lists them. "This device" goes first, on its own. */
const ORDER: readonly Exclude<HubRowId, 'device'>[] = [
  'android',
  'ios',
  'extension',
  'desktop',
  'chatgpt',
  'claude',
  'claude_code',
  'kindle_import',
];

const ASSISTANT_TAB: Record<'chatgpt' | 'claude' | 'claude_code', AssistantTab> = {
  chatgpt: 'chatgpt',
  claude: 'claude',
  claude_code: 'claudeCode',
};

/** The shell this copy of the app is, which is "This device" and not a row of its own. */
function hereSurface(device: Device): ApiSurface | undefined {
  return device.shell === 'android' ? 'android' : device.shell === 'ios' ? 'ios' : undefined;
}

function desktopOs(device: Device): boolean {
  return !device.mobile && (device.os === 'mac' || device.os === 'windows');
}

/** What can be done about a surface on this device, when it is not in use yet. */
function actionFor(
  id: Exclude<HubRowId, 'device'>,
  device: Device,
): { status: HubStatus; action: HubAction } {
  switch (id) {
    case 'android':
      if (device.os === 'ios')
        return { status: 'notHere', action: { kind: 'none', note: 'everywhere.forAndroid' } };
      return {
        status: 'notYet',
        action: { kind: 'link', href: withRef(PLAY_URL, HUB_REF), label: 'everywhere.getPlay' },
      };
    case 'ios':
      // No App Store listing exists yet; a release would bring one.
      return { status: 'notYet', action: { kind: 'none' } };
    case 'extension': {
      if (device.mobile)
        return {
          status: 'notHere',
          action: { kind: 'send', url: withRef(EXTENSION_PAGE_URL, HUB_REF), label: 'everywhere.sendLink' },
        };
      const store = extensionStore(device);
      if (store !== undefined)
        return {
          status: 'notYet',
          action: {
            kind: 'link',
            href: withRef(EXTENSION_STORES[store], HUB_REF),
            label: store === 'firefox' ? 'everywhere.addFirefox' : 'everywhere.addChrome',
          },
        };
      if (device.browser === 'safari')
        return { status: 'notHere', action: { kind: 'none', note: 'everywhere.notSafari' } };
      return {
        status: 'notYet',
        action: { kind: 'link', href: withRef(EXTENSION_PAGE_URL, HUB_REF), label: 'everywhere.seeHow' },
      };
    }
    case 'desktop':
      if (desktopOs(device))
        return {
          status: 'notYet',
          action: {
            kind: 'link',
            href: withRef(DESKTOP_PAGE_URL, HUB_REF),
            label: device.os === 'mac' ? 'everywhere.getMac' : 'everywhere.getWindows',
          },
        };
      return {
        status: 'notHere',
        action: { kind: 'send', url: withRef(DESKTOP_PAGE_URL, HUB_REF), label: 'everywhere.sendLink' },
      };
    case 'chatgpt':
    case 'claude':
    case 'claude_code':
      return {
        status: 'notYet',
        action: { kind: 'assistant', tab: ASSISTANT_TAB[id], label: 'everywhere.connect' },
      };
    case 'kindle_import':
      return { status: 'notYet', action: { kind: 'import', label: 'everywhere.import' } };
  }
}

/**
 * The hub's rows. Without an answer from the server yet (`surfaces`
 * undefined) nothing is known about the account or about what is released,
 * so every row is `unknown`: no status claimed, no link offered.
 */
export function hubRows(device: Device, surfaces: readonly ApiSurfaceStatus[] | undefined): HubRow[] {
  const by = new Map((surfaces ?? []).map((s) => [s.surface, s]));
  const here = hereSurface(device);
  const rows: HubRow[] = [{ id: 'device', status: 'here', beta: false, action: { kind: 'none' } }];
  for (const id of ORDER) {
    if (id === here) continue;
    const known = by.get(id);
    if (known === undefined) {
      rows.push({ id, status: 'unknown', beta: false, action: { kind: 'none' } });
      continue;
    }
    const release = known.release;
    const beta = release === 'beta';
    if (known.everUsed) {
      rows.push({
        id,
        status: 'connected',
        beta,
        lastUsedAt: known.lastUsedAt,
        count: known.count,
        action:
          id === 'kindle_import' ? { kind: 'import', label: 'everywhere.importMore' } : { kind: 'none' },
      });
      continue;
    }
    if (release === 'coming') {
      rows.push({ id, status: 'coming', beta: false, action: { kind: 'none' } });
      continue;
    }
    rows.push({ id, beta, ...actionFor(id, device) });
  }
  return rows;
}

/** The label of "This device", by what it is. */
export function deviceLabel(device: Device): MessageKey {
  if (device.shell === 'android') return 'everywhere.deviceAndroid';
  if (device.shell === 'ios') return 'everywhere.deviceIos';
  return 'everywhere.deviceWeb';
}
