import { Navigate, Route, Routes } from 'react-router-dom';
import { AboutSettings } from './AboutSettings.js';
import { AccountSettings } from './AccountSettings.js';
import { AppearanceSettings } from './AppearanceSettings.js';
import { ConnectedAppsSettings } from './ConnectedAppsSettings.js';
import { DataSettings } from './DataSettings.js';
import { DesktopSettings } from './DesktopSettings.js';
import { EverywhereSettings } from '@/features/everywhere/EverywhereSettings.js';
import { NotebookSettings } from './NotebookSettings.js';
import { NotificationSettings } from './NotificationSettings.js';
import { PlanSettings } from './PlanSettings.js';
import { PracticeSettings } from './PracticeSettings.js';
import { Settings } from './Settings.js';
import { SETTINGS_ROOT, type SettingsPageId } from './paths.js';

/** Each page under Settings, by its address. */
const PAGES: Record<SettingsPageId, () => React.JSX.Element> = {
  account: AccountSettings,
  notebooks: NotebookSettings,
  practice: PracticeSettings,
  notifications: NotificationSettings,
  appearance: AppearanceSettings,
  'connected-apps': ConnectedAppsSettings,
  everywhere: EverywhereSettings,
  data: DataSettings,
  plan: PlanSettings,
  about: AboutSettings,
  desktop: DesktopSettings,
};

/**
 * Settings and the pages it opens, as one chunk: the pages are small, and
 * somebody who opens Settings is about to open one of them. An address
 * under Settings that names no page — an old link, a typo — lands on
 * Settings itself rather than on "not found".
 */
export function SettingsRoutes(): React.JSX.Element {
  return (
    <Routes>
      <Route index element={<Settings />} />
      {Object.entries(PAGES).map(([path, Page]) => (
        <Route key={path} path={path} element={<Page />} />
      ))}
      <Route path="*" element={<Navigate to={SETTINGS_ROOT} replace />} />
    </Routes>
  );
}
